package com.hotel.service.impl; import com.hotel.dao.RoomDao; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; class RoomAvailabilityServiceImplTest{@Test void invalidReservationRoomDoesNotQueryDatabase(){RoomDao d=mock(RoomDao.class);var s=new RoomAvailabilityServiceImpl(d);assertTrue(s.find(0,null).isEmpty());verifyNoInteractions(d);}@Test void emptyAvailabilityIsSupported(){RoomDao d=mock(RoomDao.class);when(d.findAvailable(1,null)).thenReturn(Optional.of(List.of()));assertTrue(new RoomAvailabilityServiceImpl(d).find(1,null).orElseThrow().isEmpty());}}
